@import url('https://fonts.googleapis.com/css2?family=Montserrat:wght@400;600;700&family=Playfair+Display:ital,wght@0,700;1,700&display=swap');

/* =============================================
   KUSMI TEA – Bubble Tea 320×480 Ad
   ============================================= */

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #F4E4D4;
  font-family: "Montserrat", sans-serif;
}

/* ---- Ad root ---- */
#ad-320x480 {
  width: 320px;
  height: 480px;
  position: relative;
  overflow: hidden;
  background: #FFFFFF;
  display: flex;
  flex-direction: column;
  border: 1px solid rgba(200,16,46,0.15);
}

/* ---- Animated gradient background strip ---- */
#ad-320x480::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(
    160deg,
    rgba(247,197,72,0.18) 0%,
    rgba(249,160,63,0.10) 40%,
    rgba(244,228,212,0.25) 70%,
    rgba(200,16,46,0.07) 100%
  );
  pointer-events: none;
  z-index: 0;
}

/* ---- Floating bubbles ---- */

@keyframes floatBubble {
  0%, 100% { transform: translateY(0) scale(1); }
  50%       { transform: translateY(-12px) scale(1.07); }
}

/* ---- Header ---- */
.ad-header {
  position: relative;
  z-index: 10;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 16px 8px;
  background: #FFFFFF;
}

.ad-logo {
  height: 30px;
  width: auto;
  display: block;
  flex-shrink: 0;
}

.eyebrow {
  font-family: "Montserrat", sans-serif;
  font-weight: 700;
  font-size: 9px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: #FFFFFF;
  background: #C8102E;
  padding: 3px 8px;
  border-radius: 20px;
  line-height: 1.4;
}

/* ---- Hero image wrapper ---- */
.hero-wrap {
  position: relative;
  z-index: 5;
  width: 100%;
  height: 216px;
  flex-shrink: 0;
  overflow: hidden;
}

.hero-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center 20%;
  display: block;
  transition: transform 0.6s ease;
  transform-origin: center center;
}

#ad-320x480:hover .hero-img {
  transform: scale(1.04);
}

.kit-badge {
  position: absolute;
  top: 12px;
  right: 12px;
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: #E91E63;
  color: #FFFFFF;
  font-family: "Montserrat", sans-serif;
  font-weight: 700;
  font-size: 14px;
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: 0 2px 8px rgba(233,30,99,0.45);
  animation: pulseBadge 2.4s ease-in-out infinite;
  z-index: 10;
}

@keyframes pulseBadge {
  0%, 100% { transform: scale(1); }
  50%       { transform: scale(1.10); }
}

/* ---- Copy block ---- */
.copy-block {
  position: relative;
  z-index: 10;
  padding: 12px 16px 6px;
  flex: 1;
  display: flex;
  flex-direction: column;
  justify-content: flex-start;
  gap: 2px;
}

.subhead {
  font-family: "Montserrat", sans-serif;
  font-weight: 600;
  font-size: 10px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: #F9A03F;
}

.headline {
  font-family: "Playfair Display", sans-serif;
  font-weight: 700;
  font-size: 28px;
  line-height: 1.15;
  color: #1A1A1A;
  margin-top: 2px;
}

.headline em {
  font-style: italic;
  color: #C8102E;
}

.body-copy {
  font-family: "Montserrat", sans-serif;
  font-weight: 400;
  font-size: 10px;
  color: rgba(26,26,26,0.62);
  margin-top: 4px;
  letter-spacing: 0.04em;
}

/* ---- Kit product strip ---- */
.kit-strip {
  position: relative;
  z-index: 10;
  display: flex;
  align-items: flex-end;
  justify-content: center;
  gap: 8px;
  padding: 0 16px 8px;
}

.kit-img {
  width: 52px;
  height: 52px;
  object-fit: contain;
  filter: drop-shadow(0 2px 4px rgba(26,26,26,0.15));
  transition: transform 0.3s ease;
}

.kit-img:hover {
  transform: translateY(-4px) scale(1.05);
}

/* ---- CTA ---- */
.cta-wrap {
  position: relative;
  z-index: 10;
  padding: 0 20px 8px;
}

.cta-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  padding: 11px 16px;
  background: #C8102E;
  color: #FFFFFF;
  border-radius: 40px;
  text-decoration: none;
  transition: background 0.25s ease, transform 0.2s ease, box-shadow 0.25s ease;
  box-shadow: 0 4px 14px rgba(200,16,46,0.35);
}

.cta-btn:hover {
  background: #F9A03F;
  transform: translateY(-2px);
  box-shadow: 0 6px 18px rgba(249,160,63,0.45);
}

.cta-btn:active {
  transform: translateY(0);
  box-shadow: 0 2px 8px rgba(200,16,46,0.25);
}

.cta-label {
  font-family: "Montserrat", sans-serif;
  font-weight: 700;
  font-size: 12px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

/* ---- Footer ---- */
.ad-footer {
  position: relative;
  z-index: 10;
  padding: 0 16px 20px;
  text-align: center;
}

.ad-footer span {
  font-family: "Montserrat", sans-serif;
  font-weight: 400;
  font-size: 8px;
  color: rgba(26,26,26,0.45);
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

/* ---- Reduced motion ---- */
@media (prefers-reduced-motion: reduce) {
  .bubble,
  .kit-badge {
    animation: none;
  }
  .hero-img {
    transition: none;
  }
  .cta-btn {
    transition: none;
  }
}

